import java.io.BufferedInputStream
import kotlin.math.*

private const val EPS = 1e-6
private const val PI_CONST = Math.PI
private const val pi = PI_CONST

data class Point(var x: Double = 0.0, var y: Double = 0.0) {
    fun set(nx: Double, ny: Double) {
        x = nx
        y = ny
    }

    fun rot90(): Point {
        return Point(-y, x)
    }

    operator fun plus(other: Point): Point {
        return Point(x + other.x, y + other.y)
    }

    operator fun minus(other: Point): Point {
        return Point(x - other.x, y - other.y)
    }

    operator fun times(v: Double): Point {
        return Point(x * v, y * v)
    }

    operator fun div(v: Double): Point {
        return this * (1.0 / v)
    }
}

typealias Vec = Point

private fun PtoV(a: Point, b: Point): Vec {
    return Vec(b.x - a.x, b.y - a.y)
}

private fun dMult(a: Vec, b: Vec): Double {
    return a.x * b.x + a.y * b.y
}

private fun xMult(a: Vec, b: Vec): Double {
    return a.x * b.y - a.y * b.x
}

private fun VecMod(a: Vec): Double {
    return sqrt(dMult(a, a))
}

private fun VecMod2(a: Vec): Double {
    return dMult(a, a)
}

private fun Corner2V(a: Vec, b: Vec): Double {
    return abs(acos(dMult(a, b) / VecMod(a) / VecMod(b)))
}

private fun VecUnit(a: Vec): Vec {
    return a / VecMod(a)
}

private fun VRotate(v: Vec, alph: Double): Vec {
    val sa = sin(alph)
    val ca = cos(alph)
    return Vec(v.x * ca - v.y * sa, v.x * sa + v.y * ca)
}

private fun PRotate(p: Point, o: Point, alph: Double): Point {
    return Point(o + VRotate(PtoV(o, p), alph))
}

private fun GetVV(v: Vec): Vec {
    return VRotate(v, pi / 2)
}

private fun ShadowPOnLine(p: Point, a: Point, b: Point): Point {
    val ab = PtoV(a, b)
    val ap = PtoV(a, p)
    val alph = VecUnit(ab) * dMult(ab, ap) / VecMod(ab)
    return a + alph
}

private fun LineCrossCircle(a: Point, b: Point, o: Point, r: Double): MutableList<Point> {
    val ret = mutableListOf<Point>()
    val t = ShadowPOnLine(o, a, b)
    val ot = PtoV(o, t)
    if (VecMod(ot) - r > EPS) return ret
    if (abs(VecMod(ot) - r) < EPS) {
        ret.add(t)
        return ret
    }
    val lr = sqrt(r * r - VecMod2(ot))
    val ta = t + VecUnit(PtoV(t, a)) * lr
    val tb = t + VecUnit(PtoV(t, b)) * lr
    ret.add(ta)
    ret.add(tb)
    return ret
}

private fun PointTangentCircle(p: Point, o: Point, r: Double): MutableList<Point> {
    val x2 = VecMod2(p - o)
    var d2 = x2 - r * r
    val ret = mutableListOf<Point>()
    if (d2 < -EPS) return ret
    if (r <= EPS) {
        ret.add(o)
        ret.add(o)
        return ret
    }
    d2 = max(d2, 0.0)
    val q1 = o + (p - o) * (r * r / x2)
    val q2 = (p - o).rot90() * (-r * sqrt(d2) / x2)
    ret.add(q1 - q2)
    ret.add(q1 + q2)
    return ret
}

private fun POnSeg(p: Point, a: Point, b: Point): Boolean {
    if (abs(xMult(PtoV(a, b), PtoV(a, p))) > EPS) return false
    if (min(a.x, b.x) > p.x || p.x > max(a.x, b.x)) return false
    if (min(a.y, b.y) > p.y || p.y > max(a.y, b.y)) return false
    return true
}

private fun PDisLine(p: Point, a: Point, b: Point): Double {
    return VecMod(ShadowPOnLine(p, a, b) - p)
}

private lateinit var p: Point
private lateinit var s: Point
private var vp = 0.0
private var vs = 0.0
private var r = 0.0
private var sita = 0.0

private fun check(t: Double): Boolean {
    val len_or = VecMod(p)
    val e = Point(
        len_or * cos(sita + t * vp / len_or),
        len_or * sin(sita + t * vp / len_or)
    )
    val ccp = LineCrossCircle(s, e, Point(0.0, 0.0), r)
    if (ccp.size != 2 || (!POnSeg(ccp[0], s, e) && !POnSeg(ccp[1], s, e))) {
        return vs * t > VecMod(e - s)
    }
    val ttp1 = PointTangentCircle(s, Point(0.0, 0.0), r)
    if (PDisLine(ttp1[0], s, e) > PDisLine(ttp1[1], s, e)) {
        val tmp = ttp1[0]
        ttp1[0] = ttp1[1]
        ttp1[1] = tmp
    }
    val ttp2 = PointTangentCircle(e, Point(0.0, 0.0), r)
    if (PDisLine(ttp2[0], s, e) > PDisLine(ttp2[1], s, e)) {
        val tmp = ttp2[0]
        ttp2[0] = ttp2[1]
        ttp2[1] = tmp
    }
    val alph = Corner2V(
        PtoV(Point(0.0, 0.0), ttp1[0]),
        PtoV(Point(0.0, 0.0), ttp2[0])
    )
    return VecMod(PtoV(s, ttp1[0])) +
        VecMod(PtoV(e, ttp2[0])) +
        alph * r < vs * t
}

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val bufferSize = 1 shl 16
    private val buffer = ByteArray(bufferSize)
    private var len = 0
    private var ptr = 0

    private fun readByte(): Int {
        if (ptr >= len) {
            len = input.read(buffer)
            ptr = 0
            if (len <= 0) return -1
        }
        return buffer[ptr++].toInt()
    }

    fun nextDouble(): Double {
        var c = readByte()
        while (c <= 32 && c >= 0) c = readByte()
        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = readByte()
        }
        var res = 0.0
        while (c >= '0'.code && c <= '9'.code) {
            res = res * 10 + (c - '0'.code)
            c = readByte()
        }
        if (c == '.'.code) {
            var div = 1.0
            c = readByte()
            while (c >= '0'.code && c <= '9'.code) {
                div *= 10.0
                res += (c - '0'.code) / div
                c = readByte()
            }
        }
        return res * sign
    }

    fun hasNext(): Boolean {
        var c = readByte()
        while (c <= 32 && c >= 0) c = readByte()
        if (c < 0) return false
        ptr--
        return true
    }
}

fun main() {
    val fs = FastScanner()
    val out = StringBuilder()
    while (fs.hasNext()) {
        val px = fs.nextDouble()
        val py = fs.nextDouble()
        vp = fs.nextDouble()
        val sx = fs.nextDouble()
        val sy = fs.nextDouble()
        vs = fs.nextDouble()
        r = fs.nextDouble()
        p = Point(px, py)
        s = Point(sx, sy)

        sita = acos(p.x / VecMod(p))
        if (p.y < 0) sita = -sita

        var left = 0.0
        var right = 1e10
        while (abs(left - right) > 1e-12) {
            val mid = (left + right) * 0.5
            if (check(mid)) right = mid else left = mid
        }
        out.append(String.format("%.9f\n", left))
    }
    print(out.toString())
}

